        <div class="idc-generated-body"><div class="idc-generated-note" id="idcGeneratedNote">The card has been generated successfully.</div><div class="idc-frame-wrap"><div class="idc-card-loading" id="idcGeneratedLoading"><span class="idc-busy-spinner"></span><strong>Preparing the generated card…</strong></div><iframe id="idcGeneratedFrame" title="Generated student ID card"></iframe></div></div>
        <footer class="idc-modal-footer idc-generated-footer"><div class="idc-generated-nav"><button type="button" class="idc-btn" id="idcGeneratedPrev" aria-label="Previous generated card"><i class="fas fa-chevron-left"></i></button><span id="idcGeneratedCount">Card 1 of 1</span><button type="button" class="idc-btn" id="idcGeneratedNext" aria-label="Next generated card"><i class="fas fa-chevron-right"></i></button></div><div class="idc-generated-actions"><a class="idc-btn soft" id="idcGeneratedOpen" href="#" target="_blank" rel="noopener"><i class="fas fa-external-link-alt mr-1"></i> Open in new tab</a><button type="button" class="idc-btn primary" id="idcGeneratedContinue"><i class="fas fa-list mr-1"></i> Continue to list</button></div></footer>
    </div>
