<div class="idc-toast" id="idcToast" role="status"></div>

<script>
(() => {
    const app = document.getElementById('studentIdCardApp');
    if (!app) return;
    const $ = id => document.getElementById(id);
    const state = {status:'awaiting', page:1, perPage:25, loading:false, rows:[], lastPage:1};
    const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
    const params = () => { const p = new URLSearchParams({status:state.status,page:state.page,per_page:state.perPage}); ['search','session','faculty','department','program','level'].forEach(k => { const el = $(k === 'search' ? 'idcSearch' : 'idc'+k.charAt(0).toUpperCase()+k.slice(1)); if (el && el.value && el.value !== 'all') p.set(k,el.value); }); return p; };
    const toast = (message, error=false) => { const el=$('idcToast'); el.textContent=message; el.className='idc-toast show'+(error?' error':''); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.className='idc-toast',4200); };
    const csrfToken = () => document.querySelector('meta[name="csrf-token"]')?.content || app.dataset.csrfToken || '';
    const setLoading = value => { state.loading=value; $('idcLiveText').textContent=value?'Updating records…':'Updated just now'; $('idcApply').disabled=value; $('idcClear').disabled=value; $('idcPerPage').disabled=value; $('idcBulkGenerate').disabled=value; $('idcSelectAll').disabled=value; $('idcTableBusy').hidden=!value; $('idcTable').setAttribute('aria-busy',value?'true':'false'); if(value)$('idcRange').textContent='Loading the selected records…'; document.querySelector('.idc-tabs')?.classList.toggle('is-loading',value); document.querySelectorAll('.idc-tab').forEach(tab=>{tab.disabled=value;tab.classList.toggle('is-loading',value&&tab.classList.contains('active'));}); document.querySelectorAll('#idcPages button').forEach(button=>button.disabled=value); };
    const updateSummary = summary => { $('idcTotal').textContent=summary.total ?? 0; $('idcGenerated').textContent=summary.generated ?? 0; $('idcAwaiting').textContent=summary.awaiting ?? 0; $('idcPaid').textContent=summary.paid ?? 0; $('idcCovered').textContent=summary.school_fee_covered ?? 0; $('idcAwaitingTab').textContent=summary.awaiting ?? 0; $('idcAllTab').textContent=summary.total ?? 0; $('idcGeneratedTab').textContent=summary.generated ?? 0; $('idcIssuesTab').textContent=summary.issues ?? 0; };
    const renderRows = rows => { state.rows=rows||[]; const body=$('idcRows'); if(!state.rows.length){body.innerHTML='<tr><td colspan="7"><div class="idc-empty"><i class="fas fa-id-card"></i><strong>No matching records</strong><span>Try a different session, filter, or search term.</span></div></td></tr>'; $('idcBulkGenerate').disabled=true; return;} body.innerHTML=state.rows.map((r,i)=>`<tr><td><input type="checkbox" class="idc-row-check" data-student="${r.student_id}" data-session="${esc(r.session)}" ${r.generated?'disabled':''} aria-label="Select ${esc(r.fullname)}"></td><td><div class="idc-name">${esc(r.fullname)}</div><div class="idc-sub">${esc(r.username)} · ${esc(r.phone)}</div></td><td><div>${esc(r.program)}</div><div class="idc-sub">${esc(r.department)} · ${esc(r.faculty)} · Level ${esc(r.level)}</div></td><td>${esc(r.session)}</td><td><span class="idc-status ${r.source_key==='school_fee'?'covered':'generated'}"><i class="fas ${r.source_key==='school_fee'?'fa-graduation-cap':'fa-receipt'}"></i>${esc(r.source)}</span><div class="idc-sub">${r.paid_at?'Paid '+esc(r.paid_at):'Entry-session coverage'}</div></td><td><span class="idc-status ${r.generated?'generated':'awaiting'}"><i class="fas ${r.generated?'fa-check':'fa-hourglass-half'}"></i>${r.generated?'Generated':'Awaiting'}</span>${r.generated_at?`<div class="idc-sub">${esc(r.generated_at)}</div>`:''}</td><td><div class="idc-action-group"><button type="button" class="idc-btn soft idc-preview" data-id="${r.student_id}"><i class="fas fa-eye"></i> View details</button>${!r.generated?`<button type="button" class="idc-btn primary idc-generate" data-id="${r.student_id}" data-session="${esc(r.session)}"><i class="fas fa-print"></i> Generate</button>`:`<a class="idc-btn" href="${esc(r.card_url)}" target="_blank" rel="noopener"><i class="fas fa-file-pdf"></i> Open card</a>`}</div></td></tr>`).join(''); if(app.dataset.canIssue!=='1')body.querySelectorAll('.idc-generate,.idc-action-group a').forEach(x=>x.remove()); $('idcBulkGenerate').style.display=app.dataset.canIssue==='1'?'':'none'; $('idcBulkGenerate').disabled=app.dataset.canIssue!=='1'||!state.rows.some(r=>!r.generated); $('idcSelectAll').checked=false; };
    const renderPages = pagination => { state.lastPage=pagination.last_page||1; const pages=$('idcPages'); pages.innerHTML=''; const prev=document.createElement('button'); prev.innerHTML='<i class="fas fa-chevron-left"></i>'; prev.disabled=state.page<=1; prev.onclick=()=>{state.page--;load();}; pages.appendChild(prev); const start=Math.max(1,state.page-2),end=Math.min(state.lastPage,start+4); for(let n=start;n<=end;n++){const b=document.createElement('button');b.textContent=n;b.className=n===state.page?'active':'';b.onclick=()=>{state.page=n;load();};pages.appendChild(b);} const next=document.createElement('button');next.innerHTML='<i class="fas fa-chevron-right"></i>';next.disabled=state.page>=state.lastPage;next.onclick=()=>{state.page++;load();};pages.appendChild(next); const from=pagination.total?((state.page-1)*state.perPage)+1:0; const to=Math.min(pagination.total,state.page*state.perPage); $('idcRange').textContent=`Showing ${from}–${to} of ${pagination.total||0} record(s)`; };
    const load = async () => { if(state.loading)return; setLoading(true); try { const res=await fetch(app.dataset.dataUrl+'?'+params().toString(),{headers:{Accept:'application/json', 'X-Requested-With':'XMLHttpRequest'}}); const json=await res.json(); if(!res.ok)throw new Error(json.message||'Unable to load records.'); updateSummary(json.summary||{}); renderRows(json.rows||[]); renderPages(json.pagination||{}); $('idcTableTitle').textContent=state.status==='awaiting'?'Awaiting generation':state.status==='generated'?'Generation history':'All eligible records'; $('idcTableSubtitle').textContent=state.status==='awaiting'?'Students ready for review and issue.':state.status==='generated'?'Cards already marked as generated.':'Every eligible paid or covered record matching the filters.'; } catch(e){toast(e.message,true);} finally{setLoading(false);} };
    const populateOptions = async () => { try { const p=new URLSearchParams({faculty:$('idcFaculty').value,department:$('idcDepartment').value}); const res=await fetch(app.dataset.optionsUrl+'?'+p.toString(),{headers:{Accept:'application/json'}}); const json=await res.json(); $('idcDepartment').innerHTML='<option value="all">All departments</option>'+(json.departments||[]).map(x=>`<option value="${esc(x.code)}">${esc(x.title)}</option>`).join(''); $('idcProgram').innerHTML='<option value="all">All programmes</option>'+(json.programs||[]).map(x=>`<option value="${esc(x.code)}">${esc(x.title)}</option>`).join(''); } catch(e){toast('Academic filters could not be refreshed.',true);} };
    const openPreview = async id => { $('idcOverlay').classList.add('open'); $('idcModalTitle').textContent='Student details'; $('idcPreviewInfo').innerHTML='<div class="idc-empty"><i class="fas fa-spinner fa-spin"></i><strong>Loading student details…</strong><span>Please wait while the record is prepared.</span></div>'; try { const res=await fetch(app.dataset.previewUrl+'/'+id,{headers:{Accept:'application/json'}}); const json=await res.json(); if(!res.ok)throw new Error(json.message||'Student details unavailable.'); const s=json.student; const rows=[['Phone',s.phone],['Faculty / college',s.faculty],['Department',s.department],['Programme',s.program],['Level',s.level],['State of origin',s.state],['Nationality',s.nationality],['Emergency contact',s.emergency_contact],['Emergency phone',s.emergency_phone]]; $('idcModalTitle').textContent='Student details'; $('idcPreviewInfo').innerHTML=`<div class="idc-profile-hero"><div class="idc-profile-identity"><img class="idc-profile-avatar" src="${esc(s.picture_url)}" data-default="${esc(s.default_picture_url)}" alt="${esc(s.name)}"><div><span class="idc-modal-kicker">Official student record</span><h4>${esc(s.name)}</h4><p>${esc(s.username)}</p><span class="idc-profile-status"><i class="fas fa-circle-check"></i> Ready for ID-card issue</span></div></div><div class="idc-signature-box"><span>Signature</span>${s.signature_url?`<img class="idc-signature-image" src="${esc(s.signature_url)}" data-signature alt="Student signature">`:'<strong class="idc-signature-missing">Not provided</strong>'}</div></div><section class="idc-detail-section"><div class="idc-detail-section-title"><i class="fas fa-graduation-cap"></i><span>Academic and contact details</span></div><div class="idc-detail-grid">${rows.map(x=>`<div class="idc-info-row"><span>${esc(x[0])}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div></section>`; const avatar=$('idcPreviewInfo').querySelector('.idc-profile-avatar'); avatar?.addEventListener('error',()=>{avatar.src=avatar.dataset.default;avatar.removeAttribute('data-default');}); const signature=$('idcPreviewInfo').querySelector('[data-signature]'); signature?.addEventListener('error',()=>{signature.outerHTML='<strong class="idc-signature-missing">Not available</strong>';}); } catch(e){$('idcPreviewInfo').innerHTML='<div class="idc-empty"><i class="fas fa-triangle-exclamation"></i><strong>'+esc(e.message)+'</strong><span>Close this panel and try again.</span></div>';toast(e.message,true);} };
    const closePreview=()=>{$('idcOverlay').classList.remove('open');};
    const generatedState={results:[],index:0,message:''};
    const closeGeneratedCard=()=>{ $('idcGeneratedOverlay').classList.remove('open'); };
    const renderGeneratedCard=()=>{ const result=generatedState.results[generatedState.index]; if(!result?.card_url){toast('The generated card document could not be opened.',true);return;} const total=generatedState.results.length; const identity=[result.student_name,result.username].filter(Boolean).join(' · '); $('idcGeneratedTitle').textContent=identity||(total>1?`Generated ID card ${generatedState.index+1} of ${total}`:'Generated ID card'); $('idcGeneratedNote').textContent=generatedState.message||'The ID card is ready. Review it here, then continue to the list when you are done.'; $('idcGeneratedCount').textContent=`Card ${generatedState.index+1} of ${total}`; $('idcGeneratedPrev').disabled=generatedState.index===0; $('idcGeneratedNext').disabled=generatedState.index===total-1; $('idcGeneratedLoading').hidden=false; $('idcGeneratedFrame').src=result.card_url; $('idcGeneratedOpen').href=result.card_url; };
    const openGeneratedCard=(results,message)=>{ const list=(Array.isArray(results)?results:[results]).filter(result=>result?.card_url); if(!list.length){toast('The card was generated, but its document could not be opened.',true);return;} generatedState.results=list; generatedState.index=0; generatedState.message=message||''; renderGeneratedCard(); $('idcGeneratedOverlay').classList.add('open'); };
    const generateOne = async (student,session,button) => { const original=button.innerHTML; button.disabled=true;button.innerHTML='<span class="idc-loader">Saving…</span>'; try { const res=await fetch(app.dataset.generateUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrfToken()},body:JSON.stringify({student_id:student,session})}); const json=await res.json();if(!res.ok)throw new Error(json.message||'The card could not be marked as generated.');openGeneratedCard(json.result);toast(json.message||'The card was generated and moved to Generation history.');await load(); }catch(e){toast(e.message,true);button.disabled=false;button.innerHTML=original;} };
    const resetOne = async (student,session,button) => { const original=button.innerHTML; button.disabled=true;button.innerHTML='<span class="idc-loader">Updating…</span>'; try { const res=await fetch(app.dataset.resetUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrfToken()},body:JSON.stringify({student_id:student,session})}); const json=await res.json();if(!res.ok)throw new Error(json.message||'The card could not be returned to awaiting.');toast(json.message||'Card returned to awaiting.');await load(); }catch(e){toast(e.message,true);button.disabled=false;button.innerHTML=original;} };
    $('idcRows').addEventListener('click',e=>{const preview=e.target.closest('.idc-preview');if(preview)openPreview(preview.dataset.id);const gen=e.target.closest('.idc-generate');if(gen)generateOne(gen.dataset.id,gen.dataset.session,gen);const reset=e.target.closest('.idc-reset');if(reset)resetOne(reset.dataset.id,reset.dataset.session,reset);}); $('idcGeneratedFrame').addEventListener('load',()=>{$('idcGeneratedLoading').hidden=true;});
    $('idcApply').onclick=()=>{state.page=1;load();}; $('idcClear').onclick=()=>{['idcSearch','idcDepartment','idcProgram','idcLevel'].forEach(id=>$(id).value=id==='idcSearch'?'':'all');$('idcSession').value='{{ $idCardCurrentSession }}';$('idcFaculty').value='all';populateOptions();state.page=1;load();}; $('idcFaculty').onchange=()=>{populateOptions();}; $('idcDepartment').onchange=()=>{populateOptions();}; $('idcPerPage').onchange=e=>{state.perPage=Number(e.target.value)||25;state.page=1;load();}; $('idcSelectAll').onchange=e=>document.querySelectorAll('.idc-row-check:not(:disabled)').forEach(x=>x.checked=e.target.checked); document.querySelectorAll('.idc-tab').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('.idc-tab').forEach(x=>x.classList.remove('active'));tab.classList.add('active');state.status=tab.dataset.status;state.page=1;load();}); $('idcClose').onclick=closePreview; $('idcOverlay').onclick=e=>{if(e.target.id==='idcOverlay')closePreview();}; $('idcGeneratedClose').onclick=closeGeneratedCard; $('idcGeneratedContinue').onclick=closeGeneratedCard; $('idcGeneratedPrev').onclick=()=>{if(generatedState.index>0){generatedState.index--;renderGeneratedCard();}}; $('idcGeneratedNext').onclick=()=>{if(generatedState.index<generatedState.results.length-1){generatedState.index++;renderGeneratedCard();}}; $('idcGeneratedOverlay').onclick=e=>{if(e.target.id==='idcGeneratedOverlay')closeGeneratedCard();}; $('idcBulkGenerate').onclick=async()=>{const items=[...document.querySelectorAll('.idc-row-check:checked')].map(x=>({student_id:x.dataset.student,session:x.dataset.session}));if(!items.length){toast('Select at least one awaiting card.',true);return;}const btn=$('idcBulkGenerate');btn.disabled=true;btn.innerHTML='<span class="idc-loader">Processing…</span>';try{const res=await fetch(app.dataset.bulkUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrfToken()},body:JSON.stringify({items})});const json=await res.json();if(!res.ok)throw new Error(json.message||'Bulk generation failed.');if(json.results?.length)openGeneratedCard(json.results,`${json.done||json.results.length} card(s) generated. Use the arrows to review every generated card.`);toast(json.message||'Selected cards were generated and moved to Generation history.');await load();}catch(e){toast(e.message,true);}finally{btn.innerHTML='<i class="fas fa-print mr-1"></i> Mark selected generated';btn.disabled=false;}};
    // Keep academic selections when the dependent lists refresh. This avoids
    // silently resetting a chosen department or programme before Apply.
    $('idcFaculty').onchange=()=>{$('idcDepartment').value='all';$('idcProgram').value='all';populateOptions();};
    $('idcDepartment').onchange=()=>{const department=$('idcDepartment').value;const program=$('idcProgram').value;populateOptions().then(()=>{if([...$('idcDepartment').options].some(x=>x.value===department))$('idcDepartment').value=department;if([...$('idcProgram').options].some(x=>x.value===program))$('idcProgram').value=program;});};
    document.querySelector('[data-close-idc]')?.addEventListener('click',closePreview);

    // Generated records can be returned to the awaiting queue without a full
    // page reload. The observer adds the action after each table render and
    // delegates the click to the existing reset handler above.
    const addGeneratedResetActions=()=>{if(app.dataset.canReset!=='1')return;state.rows.forEach((row,index)=>{if(!row.generated)return;const tableRow=$('idcRows').children[index];const group=tableRow?.querySelector('.idc-action-group');if(!group||group.querySelector('.idc-reset'))return;const button=document.createElement('button');button.type='button';button.className='idc-btn danger idc-reset';button.dataset.id=row.student_id;button.dataset.session=row.session;button.innerHTML='<i class="fas fa-rotate-left"></i> Return to awaiting';group.appendChild(button);});};
    new MutationObserver(addGeneratedResetActions).observe($('idcRows'),{childList:true});
    populateOptions(); load();
})();
</script>

<script>
(() => {
    const app = document.getElementById('studentIdCardApp');
    if (!app) return;
    const $ = id => document.getElementById(id);
    const csrf = () => document.querySelector('meta[name="csrf-token"]')?.content || app.dataset.csrfToken || '';
    const cache = new Map();
    let currentStudent = null;
    let currentSession = '';
    const syncModalScrollState = () => {
        document.body.classList.toggle('idc-modal-open', !!document.querySelector('.idc-overlay.open'));
    };
    document.querySelectorAll('.idc-overlay').forEach(overlay => {
        new MutationObserver(syncModalScrollState).observe(overlay, {attributes: true, attributeFilter: ['class']});
    });
    syncModalScrollState();
    let pictureProcessing = Promise.resolve();
    let picturePreviewReady = false;
    const showPictureFile = file => {
        const preview = $('idcPicturePreview'), name = $('idcPictureName'); if (!file) return;
        name.textContent = file.name; picturePreviewReady = false;
        if (!file.type.startsWith('image/')) { preview.innerHTML = '<i class="fas fa-file"></i>'; return; }
        const reader = new FileReader(); reader.onload = event => { preview.innerHTML = '<img class="idc-media-preview-image" src="' + event.target.result + '" alt="Selected photo preview">'; }; reader.readAsDataURL(file);
        const status = $('idcPictureStatus'); status.className = 'idc-photo-processing'; status.innerHTML = '<span class="idc-loader">Preparing photo…</span>';
        const payload = new FormData(); payload.append('_token', csrf()); payload.append('student_id', $('idcMediaStudent')?.value || ''); payload.append('picture', file); payload.append('preview', '1');
        pictureProcessing = fetch(app.dataset.mediaPreviewUrl, {method:'POST', headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':csrf()}, body:payload}).then(async response => { const data = await response.json(); if (!response.ok) throw new Error(data.message || 'The photo could not be prepared.'); preview.innerHTML = '<img class="idc-media-preview-image" src="' + data.preview + '" alt="Processed photo preview">'; picturePreviewReady = true; status.className = 'idc-photo-processing success'; status.innerHTML = '<i class="fas fa-circle-check"></i> Photo prepared successfully'; }).catch(error => { picturePreviewReady = false; status.className = 'idc-photo-processing error'; status.textContent = error.message; throw error; });
    };
    const setupPictureUpload = () => { const input=$('idcPictureInput'), drop=$('idcPictureDrop'); if(!input||!drop)return; drop.addEventListener('click',()=>input.click()); input.addEventListener('change',()=>{if(input.files?.[0])showPictureFile(input.files[0]);}); ['dragenter','dragover'].forEach(type=>drop.addEventListener(type,event=>{event.preventDefault();drop.classList.add('is-dragging');})); ['dragleave','drop'].forEach(type=>drop.addEventListener(type,event=>{event.preventDefault();drop.classList.remove('is-dragging');})); drop.addEventListener('drop',event=>{const file=event.dataTransfer?.files?.[0];if(!file)return;try{input.files=event.dataTransfer.files;}catch(_){}showPictureFile(file);}); };
    const setupSignatureCanvas = () => { const canvas=$('idcSignatureCanvas'), input=$('idcSignatureInput'), clear=$('idcSignatureClear'); if(!canvas||!input)return; const context=canvas.getContext('2d'); context.lineWidth=4;context.lineCap='round';context.lineJoin='round';context.strokeStyle='#152d42';let drawing=false,hasInk=false; const point=event=>{const rect=canvas.getBoundingClientRect();const source=event.touches?.[0]||event;return{x:(source.clientX-rect.left)*(canvas.width/rect.width),y:(source.clientY-rect.top)*(canvas.height/rect.height)}}; const start=event=>{event.preventDefault();drawing=true;const p=point(event);context.beginPath();context.moveTo(p.x,p.y)}; const move=event=>{if(!drawing)return;event.preventDefault();const p=point(event);context.lineTo(p.x,p.y);context.stroke();hasInk=true}; const finish=()=>{if(!drawing)return;drawing=false;if(!hasInk)return;input.pendingImage=new Promise(resolve=>canvas.toBlob(blob=>{if(blob){const transfer=new DataTransfer();transfer.items.add(new File([blob],'signature.png',{type:'image/png'}));input.files=transfer.files;$('idcSignatureName').textContent='Drawn signature ready'}resolve()},'image/png'))}; canvas.addEventListener('pointerdown',start);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointerleave',finish);clear?.addEventListener('click',()=>{context.clearRect(0,0,canvas.width,canvas.height);hasInk=false;input.value='';input.pendingImage=null;$('idcSignatureName').textContent='Draw a signature or choose an image'}); input.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;const image=new Image();image.onload=()=>{context.clearRect(0,0,canvas.width,canvas.height);const scale=Math.min(canvas.width/image.width,canvas.height/image.height),width=image.width*scale,height=image.height*scale;context.drawImage(image,(canvas.width-width)/2,(canvas.height-height)/2,width,height);hasInk=true;$('idcSignatureName').textContent=file.name};image.src=URL.createObjectURL(file)}); };
    setupPictureUpload(); setupSignatureCanvas();
    const resetUploadCards=()=>{const input=$('idcPictureInput'),preview=$('idcPicturePreview'),name=$('idcPictureName'),status=$('idcPictureStatus');if(input)input.value='';if(preview)preview.innerHTML='<i class="fas fa-cloud-arrow-up"></i>';if(name)name.textContent='No file selected';if(status){status.className='idc-photo-processing';status.textContent=''}picturePreviewReady=false;pictureProcessing=Promise.resolve();const signature=$('idcSignatureInput'),canvas=$('idcSignatureCanvas'),signatureName=$('idcSignatureName');if(signature)signature.value='';if(canvas)canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);if(signatureName)signatureName.textContent='Draw a signature or choose an image';};
    const notice = (message, error = false) => {
        const el = $('idcToast');
        el.textContent = message;
        el.className = 'idc-toast show' + (error ? ' error' : '');
        clearTimeout(notice.timer);
        notice.timer = setTimeout(() => el.className = 'idc-toast', 4500);
    };
    const loadDetails = async id => {
        if (!cache.has(id)) {
            const response = await fetch(app.dataset.previewUrl + '/' + id, {headers: {Accept: 'application/json'}});
            const payload = await response.json();
            if (!response.ok) throw new Error(payload.message || 'Student details unavailable.');
            cache.set(id, payload.student);
        }
        return cache.get(id);
    };
    const refreshList = () => document.querySelector('.idc-tab.active')?.click();
    const showPanels = student => {
        currentStudent = student.id;
        currentSession = $('idcSession')?.value || '';
        $('idcMediaStudent').value = student.id;
        $('idcIssueStudent').value = student.id;
        $('idcIssueSession').value = currentSession === 'all' ? '' : currentSession;
        $('idcMediaPanel').hidden = app.dataset.canMedia !== '1';
        $('idcIssuePanel').hidden = app.dataset.canMarkIssue !== '1';
        const missing = Array.isArray(student.missing_media) ? student.missing_media : [];
        const status = $('idcPreviewInfo').querySelector('.idc-profile-status');
        if (status) {
            status.className = 'idc-profile-status ' + (student.media_ready && !student.issue ? '' : 'idc-media-warning');
            status.innerHTML = student.issue
                ? '<i class="fas fa-triangle-exclamation"></i> Issue recorded'
                : (student.media_ready ? '<i class="fas fa-circle-check"></i> Documents ready' : '<i class="fas fa-circle-exclamation"></i> Missing ' + missing.join(' and '));
        }
        const issuePanel = $('idcIssuePanel');
        const existing = issuePanel.querySelector('.idc-issue-note');
        if (existing) existing.remove();
        if (student.issue) {
            const note = document.createElement('div');
            note.className = 'idc-issue-note';
            note.innerHTML = '<strong>Open issue:</strong> ' + String(student.issue.description || '').replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
            issuePanel.insertBefore(note, issuePanel.querySelector('form'));
        }
        const resolveButton = $('idcIssueResolve');
        resolveButton.hidden = !student.issue || app.dataset.canResolveIssue !== '1';
        resolveButton.dataset.issueId = student.issue?.id || '';
    };
    document.addEventListener('click', event => {
        const button = event.target.closest('.idc-preview');
        if (!button) return;
        const id = button.dataset.id;
        setTimeout(async () => {
            try { showPanels(await loadDetails(id)); }
            catch (error) { notice(error.message, true); }
        }, 180);
    });
    const syncRows = async () => {
        const rows = [...document.querySelectorAll('#idcRows tr')];
        for (const row of rows) {
            const check = row.querySelector('.idc-row-check');
            const generate = row.querySelector('.idc-generate');
            if (!check || !generate) continue;
            try {
                const student = await loadDetails(check.dataset.student);
                if (!student.media_ready || student.issue) {
                    check.disabled = true;
                    if (generate.dataset.idcLocked !== '1') {
                        generate.disabled = true;
                        generate.classList.add('disabled-action');
                        generate.title = student.issue ? 'Resolve the open ID-card issue first.' : 'Add both a profile photo and signature first.';
                        generate.innerHTML = '<i class="fas fa-lock"></i> ' + (student.issue ? 'Issue recorded' : 'Documents missing');
                        generate.dataset.idcLocked = '1';
                    }
                }
                if (student.issue) {
                    const statusCell = row.querySelector('td:nth-child(6)');
                    if (statusCell && !statusCell.querySelector('.idc-issue-description')) {
                        const note = document.createElement('div');
                        note.className = 'idc-sub idc-issue-description';
                        note.textContent = student.issue.description || 'Correction required';
                        statusCell.appendChild(note);
                    }
                }
            } catch (_) { /* The normal table remains usable if one preview request fails. */ }
        }
    };
    new MutationObserver(() => setTimeout(syncRows, 40)).observe($('idcRows'), {childList: true, subtree: true});
    $('idcMediaForm')?.addEventListener('submit', async event => {
        event.preventDefault();
        const button = $('idcMediaSave');
        const form = event.currentTarget;
        if (!form.picture.files.length && !form.signiture.files.length) { notice('Choose a photo or signature before saving.', true); return; }
        if (form.picture.files.length && !picturePreviewReady) { notice('Prepare the selected photo first and wait for the preview to finish.', true); return; }
        if (form.signiture.pendingImage) await form.signiture.pendingImage;
        button.disabled = true; button.innerHTML = '<span class="idc-loader">Saving…</span>';
        try {
            const response = await fetch(app.dataset.mediaUrl, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': csrf()}, body: new FormData(form)});
            const payload = await response.json();
            if (!response.ok) throw new Error(payload.message || 'The documents could not be saved.');
            cache.delete(currentStudent); notice(payload.message || 'Documents updated.'); form.reset(); resetUploadCards();
            const student = await loadDetails(currentStudent); showPanels(student); refreshList();
        } catch (error) { notice(error.message, true); }
        finally { button.disabled = false; button.innerHTML = '<i class="fas fa-save"></i> Save documents'; }
    });
    $('idcIssueForm')?.addEventListener('submit', async event => {
        event.preventDefault();
        const button = $('idcIssueSave');
        const form = event.currentTarget;
        button.disabled = true; button.innerHTML = '<span class="idc-loader">Recording…</span>';
        try {
            const response = await fetch(app.dataset.issueUrl, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': csrf()}, body: new FormData(form)});
            const payload = await response.json();
            if (!response.ok) throw new Error(payload.message || 'The issue could not be recorded.');
            cache.delete(currentStudent); notice(payload.message || 'Issue recorded.'); form.reset(); $('idcIssueStudent').value = currentStudent; refreshList();
            const student = await loadDetails(currentStudent); showPanels(student);
        } catch (error) { notice(error.message, true); }
        finally { button.disabled = false; button.innerHTML = '<i class="fas fa-flag"></i> Mark as issue'; }
    });
    $('idcIssueResolve')?.addEventListener('click', async event => {
        const button = event.currentTarget;
        if (!button.dataset.issueId) return;
        button.disabled = true; button.innerHTML = '<span class="idc-loader">Resolving…</span>';
        try {
            const body = new FormData(); body.append('issue_id', button.dataset.issueId);
            const response = await fetch(app.dataset.resolveIssueUrl, {method: 'POST', headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': csrf()}, body});
            const payload = await response.json();
            if (!response.ok) throw new Error(payload.message || 'The issue could not be resolved.');
            cache.delete(currentStudent); notice(payload.message || 'Issue resolved.'); refreshList();
            const student = await loadDetails(currentStudent); showPanels(student);
        } catch (error) { notice(error.message, true); }
        finally { button.disabled = false; button.innerHTML = '<i class="fas fa-check"></i> Resolve current issue'; }
    });
    document.querySelectorAll('.idc-tab').forEach(tab => tab.addEventListener('click', () => {
        if (tab.dataset.status === 'issues') {
            setTimeout(() => {
                $('idcTableTitle').textContent = 'ID cards needing attention';
                $('idcTableSubtitle').textContent = 'Open corrections recorded by authorised staff. Generation stays blocked until resolved.';
            }, 40);
        }
    }));
})();
</script>
